use std::collections::HashMap;
use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut map = HashMap::new();

    if let Some(array) = input.as_array() {
        for item in array {
            if let Some(pair) = item.as_array() {
                if let Some(key) = pair.get(0).and_then(|v| v.as_i64()) {
                    if let Some(value) = pair.get(1).and_then(|v| v.as_i64()) {
                        map.insert(key, value);
                    }
                }
            }
        }
    }

    let mut result = map.into_iter().collect::<Vec<_>>();
    result.sort_by_key(|&(key, _)| key);

    let mut sorted_array = Vec::with_capacity(result.len());
    for (key, value) in result {
        sorted_array.push(Value::Array(vec![Value::Number(key.into()), Value::Number(value.into())]));
    }

    Value::Array(sorted_array)
}
